/*
 * Verifies each public/<name>.mjs and server/<name>.cjs pair still agrees.
 * The convention is hand-maintained, so nothing otherwise stops the copies
 * drifting -- and a drifted pair means the client and server disagree about
 * geometry, which surfaces as position corrections rather than an error.
 */
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';

const require = createRequire(import.meta.url);

// Pairs generated by mirroring the ESM copy are compared byte for byte.
const MIRRORED = ['collision', 'motion', 'headset', 'flags', 'voice-channels', 'tank-parts'];
// Pairs written by hand on both sides are compared by exported shape.
const HAND_WRITTEN = ['shots', 'teams'];

let failed = false;
const fail = (msg) => { console.error(msg); failed = true; };

for (const name of [...MIRRORED, ...HAND_WRITTEN]) {
  const client = await import(`../public/${name}.mjs`);
  const server = require(`../server/${name}.cjs`);

  const mirrored = MIRRORED.includes(name);
  for (const key of Object.keys(client)) {
    if (!(key in server)) {
      // Hand-written pairs are deliberately asymmetric: each side carries the
      // helpers only it needs. Shared names are what must agree.
      if (mirrored) fail(`${name}: server copy is missing ${key}`);
      continue;
    }
    const a = client[key];
    const b = server[key];
    if (typeof a !== typeof b) {
      fail(`${name}: ${key} is ${typeof a} on the client, ${typeof b} on the server`);
    } else if (typeof a === 'function' && a.length !== b.length) {
      // This is the check that catches a parameter added to only one copy.
      fail(`${name}: ${key} takes ${a.length} args on the client, ${b.length} on the server`);
    } else if (typeof a === 'number' && a !== b) {
      fail(`${name}: ${key} is ${a} on the client, ${b} on the server`);
    }
  }
  if (mirrored) {
    for (const key of Object.keys(server)) {
      if (!(key in client)) fail(`${name}: client copy is missing ${key}`);
    }
  }
}

// The mirrored pairs must also match line for line, so a changed function body
// cannot slip through with an unchanged signature.
for (const name of MIRRORED) {
  const normalize = (text) => text
    .replace(/^export (function|const|let) /gm, '$1 ')
    .replace(/\nmodule\.exports = \{[\s\S]*?\};\s*$/, '')
    .trim();
  const a = normalize(readFileSync(`public/${name}.mjs`, 'utf8')).split('\n');
  const b = normalize(readFileSync(`server/${name}.cjs`, 'utf8')).split('\n');
  const at = a.findIndex((line, i) => line !== b[i]);
  if (at !== -1 || a.length !== b.length) {
    fail(`${name}: bodies differ at line ${at + 1}\n  mjs: ${JSON.stringify(a[at])}\n  cjs: ${JSON.stringify(b[at])}`);
  }
}

if (failed) process.exit(1);
console.log('shared client/server pairs are in sync');
